import {
  IconAdd,
  IconExpandLess,
  IconExpandMore,
  IconMinimize,
} from "@airbus/icons";
import { focus, svgColor, svgUri } from "../../helpers";
import { Button } from "../Button";
import { StyleFn } from "..";

export const Collapsible: StyleFn = (theme, mode) => {
  const { color, font, opacity, size } = theme;
  const { root: rootButtonStyles } = Button(theme, mode);
  const { focusWithPseudo } = focus(theme, mode);

  const colors = {
    title: color.text.neutral.default[mode],
    hoverBG: color.surface.interaction.hover[mode],
    arrow: color.text.accent.corporate[mode],
    border: color.border.neutral.default[mode],
    text: color.text.neutral.strong[mode],
    panelBorder: color.border.neutral.moderate[mode],
  };

  const disabledButton = {
    opacity: 1,
    cursor: "not-allowed",
    pointerEvents: "unset",
    "&:hover": {
      backgroundColor: color.surface.interaction.default[mode],
    },
  };

  return {
    root: {
      display: "flex",
      flexDirection: "column",
      border: `1px solid ${colors.border}`,
      borderRadius: "3px",
      marginBottom: size.spacing[8],
    },
    _expanded: {
      overflowY: "auto",
      "& $button": {
        ...focusWithPseudo({
          pseudo: "before",
          radius: "2px",
          offset: 0,
          borderWidth: "3px",
          transparentBorder: false,
        }),
        "&:after": {
          backgroundImage: svgUri(svgColor(IconExpandLess.data, colors.arrow)),
        },
        "&:hover": {
          borderBottomLeftRadius: 0,
          borderBottomRightRadius: 0,
        },
      },
    },
    _autofit: {
      flex: 1,
    },
    _disabled: {
      opacity: opacity.disabled,
      "& $button:disabled": disabledButton,
      "& $button[aria-disabled='true']": disabledButton,
    },
    header: {
      // increase specificity and defeat global
      "&$header": {
        all: "initial",
        margin: 0,
        padding: 0,
        fontFamily: "inherit",
        fontWeight: font.weight.bold,
        color: colors.title,
      },
    },
    button: {
      all: "initial",
      extend: [
        rootButtonStyles,
        focusWithPseudo({
          borderWidth: "3px",
          pseudo: "before",
          radius: "2px",
          offset: 0,
          transparentBorder: false,
        }),
      ],
      paddingBottom: size.spacing[8],
      paddingTop: size.spacing[8],
      color: colors.title,
      width: "100%",
      display: "flex",
      flexDirection: "column",
      borderRadius:"2px",
      alignItems: "flex-start",
      position: "relative",
      fontSize: font.size.medium,
      "&:hover": {
        backgroundColor: colors.hoverBG,
      },
      "&:after": {
        position: "absolute",
        content: "''",
        top: size.spacing[8],
        right: size.spacing[16],
        bottom: 0,
        width: size.spacing[24],
        height: size.spacing[24],
        backgroundRepeat: "no-repeat",
        backgroundPosition: "left 0 top 50%",
        backgroundImage: svgUri(svgColor(IconExpandMore.data, colors.arrow)),
        transition: "background-image 0.2s ease-in-out, top 0.2s ease-in-out",
      },
    },
    content: {
      padding: size.spacing[16],
      paddingTop: size.spacing[8],
      color: colors.text,
      overflowY: "auto",
    },
    _filterpanel: {
      border: "none",
      marginBottom: 0,
      "& $header": {
        borderBottom: `1px solid ${colors.panelBorder}`,
        marginBottom: size.spacing[4],
      },
      "& $content": {
        paddingLeft: size.spacing[4],
        paddingRight: size.spacing[4],
      },
      "& $button": {
        paddingLeft: size.spacing[2],
        paddingRight: 0,
        extend: focusWithPseudo({
          pseudo: "before",
          radius: 0,
          offset: 0,
          borderWidth: "3px",
          transparentBorder: false,
        }),
      },
      "& $button:after": {
        right: 0,
        top: size.spacing[8],
        backgroundImage: svgUri(svgColor(IconAdd.data, colors.arrow)),
      },
      "&$_expanded $button:after": {
        top: size.spacing[0],
        backgroundImage: svgUri(svgColor(IconMinimize.data, colors.arrow)),
      },
    },
  };
};
